import codecs
import encodings
for attempt in range(2):
    try:
        import encodings.mbcs
    except ImportError as error:
        assert type(error) is ImportError
        assert error.args == ("cannot import name 'mbcs_encode' from 'codecs' (" + codecs.__file__ + ")",)
        assert error.name == 'codecs'
        assert error.path == codecs.__file__
        assert error.name_from == 'mbcs_encode'
        assert error.__context__ is None and error.__cause__ is None
    else:
        assert False
    assert not hasattr(encodings, 'mbcs')
    try:
        codecs.lookup('mbcs')
    except LookupError as error:
        assert type(error) is LookupError
        assert error.args == ('unknown encoding: mbcs',)
    else:
        assert False
assert encodings._cache['mbcs'] is None

