import _codecs
failure = KeyboardInterrupt('guest')
class Mapping:
    def __getitem__(self, point):
        raise failure
def recover(error):
    raise failure
_codecs.register_error('custom', recover)
try:
    _codecs.charmap_encode('a', 'custom', Mapping())
except KeyboardInterrupt as error:
    assert error is failure, 'mapping identity'
    assert error.__traceback__ is not None, 'mapping traceback'
    assert not hasattr(error, '__notes__'), 'mapping notes'
else:
    assert False

